<div class={`appshell shell-${shellId}`} data-slice="appshell-svelte"><div class="wallpaper"></div>{#if shellId==="macos"}<MacShell apps={manifest.apps} brand={manifest.brand}/>{:else if shellId==="windows"}<WindowsShell apps={manifest.apps}/>{:else if shellId==="android"}<MobileShell apps={manifest.apps} kind="android"/>{:else}<MobileShell apps={manifest.apps} kind="ios"/>{/if}<AppLauncher apps={manifest.apps}/><CommandPalette apps={manifest.apps}/><Notifications/><InspectorPanel/><SystemSheets/><Slot region="overlay"/><Slot region="notifications"/></div>
